    words = s.split(' ')

    for word in words:
        sorted_word = ''.join(sorted(word))
        result.append(sorted_word)

    ordered_string = ' '.join(result)

    # Now we need to maintain the spaces in the original string
    final_result = []
    word_index = 0

    for char in s:
        if char == ' ':
